# -*- coding: utf-8 -*-
from pathlib import Path
personal=[('自我觉察',2,'回想一次影响课堂互动的情绪或假设：当时还有哪些解释？','选一节课，在课后写下一个判断和一个值得再了解的问题。'),('自我管理',3,'哪些情境让您更难保持平静或照顾自己？','选一个可持续的小恢复习惯，并请同事协助创造时间。'),('社会觉察',4,'哪些学生的经历与资源还没有充分进入课堂？','向学生开放一个安全的分享渠道，用他们的反馈调整一次活动。'),('关系技能',2,'与哪些学生的沟通比较困难？您对这种困难有哪些假设？','尝试一次不急于解决问题的倾听，并记录对方希望得到的支持。'),('负责任决策',3,'一次决定对不同学生可能产生哪些意料之外的影响？','下次决定前收集两种不同视角，并在实施后回看结果。')]
practice=[('温暖与支持','哪些日常互动让每位学生感到被看见？'),('责任与选择','学生在哪些事情上有真实的选择和发言空间？'),('以学生为中心的问题解决','出现冲突时，学生怎样参与共同寻找解决办法？'),('语言的力量','您的语言如何传递期待与归属感？'),('合作学习','小组任务中，怎样让不同学生都能贡献？'),('小组讨论','谁经常发言，谁较少被听见？'),('学生自我反思与自评','学生有哪些机会判断自己的进步并修改作品？'),('平衡教学','直接讲授与主动探索如何随学生需求调整？'),('期待与挑战','挑战性任务是否配有每位学生需要的支持？'),('社会情绪能力培养','学生在哪里有机会练习、获得反馈并运用这些能力？')]
header='''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>教师的社会情绪反思</title><style>*{box-sizing:border-box}body{margin:0;background:#f3f6f5;color:#233a38;font:16px/1.75 system-ui,sans-serif}main{max-width:960px;margin:auto;padding:30px 22px 64px}.hero{background:#dcebe7;border-radius:24px;padding:36px}h1{font-size:clamp(30px,5vw,46px);line-height:1.2;margin:8px 0}h2{margin-top:36px}.tag{font-size:13px;color:#51746c;font-weight:bold;letter-spacing:.06em}.note,.chart,.card{background:white;border-radius:16px;padding:22px;margin:14px 0}.row{display:grid;grid-template-columns:180px 1fr 60px;gap:12px;align-items:center;margin:12px 0}.track{height:12px;border-radius:8px;background:#e7efec}.fill{height:12px;border-radius:8px;background:#72a999}.card h3{margin:0}.prompt{color:#3d7467;font-weight:600}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}.grid .card{margin:0}.foot{font-size:13px;color:#5b6d69}@media(max-width:620px){.grid{grid-template-columns:1fr}.row{grid-template-columns:1fr 50px}.track{grid-column:1/-1}}</style></head><body><main><section class="hero"><div class="tag">模拟样稿 · 教师自我反思</div><h1>把觉察带回课堂</h1><p>先了解自己，再观察教学情境。这里的线索用于支持专业成长，也需要结合学生声音、工作条件和具体经历理解。</p></section><div class="note"><strong>这是模拟数据。</strong>个人能力各项平均回答范围为 1–4：从强烈不同意到强烈同意。数字表示一次自评，不是经过验证的能力等级。教学实践单独反思，不与个人能力合成总分。</div><h2>个人社会情绪能力</h2><div class="chart" role="img" aria-label="模拟均分：自我觉察2，自我管理3，社会觉察4，关系技能2，负责任决策3；范围1至4">'''
rows=''.join(f'<div class="row"><span>{name}</span><div class="track"><div class="fill" style="width:{(value-1)/3*100:.2f}%"></div></div><strong>{value:.2f}</strong></div>' for name,value,_,_ in personal)
cards=''.join(f'<article class="card"><h3>{name} · {value:.2f}</h3><p>{question}</p><p class="prompt">可以试试：{action}</p></article>' for name,value,question,action in personal)
practices=''.join(f'<article class="card"><h3>{name}</h3><p>{question}</p></article>' for name,question in practice)
footer='''<h2>制定一个可行的小行动</h2><p>选择一个您愿意尝试的改变，约定时间、需要的支持和观察方式；之后结合学生反馈与同事讨论调整。</p><p class="foot">此页为模拟样稿。AIR 将本工具用于自我反思与专业学习，其2022版尚未经实证检验，不适用于高风险决策。<a href="https://www.air.org/sites/default/files/2022-12/GTL-Educator-Self-Assessment-Refreshed-2014-508.pdf">查看原始工具</a>。</p></main></body></html>'''
Path(__file__).with_name('report.html').write_text(header+rows+'</div>'+cards+'<h2>教学实践：十个反思入口</h2><p>这一部分不依据个人能力得分推断课堂表现；请结合具体教学与学生反馈逐项思考。</p><div class="grid">'+practices+'</div>'+footer)
